define('taoQtiItem/qtiCreator/widgets/interactions/sliderInteraction/Widget',['taoQtiItem/qtiCreator/widgets/interactions/Widget', 'taoQtiItem/qtiCreator/widgets/interactions/sliderInteraction/states/states', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/SliderInteraction'], function (Widget, states, SliderInteraction) {
  var SliderInteractionWidget = Widget.clone();
  SliderInteractionWidget.initCreator = function () {
    this.registerStates(states);
    Widget.initCreator.call(this);
    this.$container.find('.qti-slider').attr('disabled', 'disabled');
    var $itemBody = this.$container.closest('.qti-itemBody');
    $itemBody.on('item-dir-changed', () => {
      var interaction = this.element;
      interaction.getContainer().find('.qti-slider,.qti-slider-values,.qti-slider-cur-value,.qti-slider-value').remove();
      SliderInteraction.render(interaction);
    });
  };
  return SliderInteractionWidget;
});
